import polars as pl

def solve(df: pl.DataFrame) -> pl.DataFrame:
    return df.group_by("keys").agg(
        pl.col("values").map_batches(
            lambda s: (s - s.mean()).to_list(),
            return_dtype=pl.List(pl.Float64)
        ).alias("values")
    )

