def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        (
            df.group_by("group").agg(
                pl.map_groups(
                    exprs=["a", "b"],
                    function=lambda list_of_series: (
                        list_of_series[0] / list_of_series[0].sum() + list_of_series[1]
                    ),
                    return_dtype=pl.Float64,
                ).alias("my_custom_aggregation")
            )
        ).sort("group")
    )

solver_code:
def solve(df: pl.DataFrame) -> pl.DataFrame:
    return (
        df
        .with_columns(
            pl.col("a").sum().over("group").alias("group_sum_a")
        )
        .with_columns(
            (pl.col("a") / pl.col("group_sum_a") + pl.col("b")).over("group").alias("my_custom_aggregation")
        )
        .select("group", "my_custom_aggregation")
        .sort("group")
    )

