def solve(gdp2: pl.LazyFrame, pop2: pl.LazyFrame) -> pl.DataFrame:
    gdp2 = gdp2.sort("country", "date")
    pop2 = pop2.sort("country", "date")
    return pop2.join_asof(gdp2, by="country", on="date", strategy="nearest").collect()

def solve(df: pl.DataFrame) -> pl.DataFrame:
